142	func (a errorMsgs) JSON() any {
143		switch length := len(a); length {
144		case 0:
145			return nil
146		case 1:
147			return a.Last().JSON()
148		default:
149			jsonData := make([]any, length)
150			for i, err := range a {
151				jsonData[i] = err.JSON()
152			}
153			return jsonData
154		}
155	}
