162	func (a errorMsgs) String() string {
163		if len(a) == 0 {
164			return ""
165		}
166		var buffer strings.Builder
167		for i, msg := range a {
168			fmt.Fprintf(&buffer, "Error #%02d: %s\n", i+1, msg.Err)
