// Exact reproduction from the bug report.
func TestBugReportRepro(t *testing.T) {
	for _, name := range []string{"gin.New", "gin.Default"} {
		t.Run(name, func(t *testing.T) {
			gin.SetMode(gin.TestMode)
			var r *gin.Engine
			if name == "gin.New" {
				r = gin.New()
			} else {
				r = gin.Default()
			}
			if got := do(r, http.MethodGet, "/test/john/smith/is/super/great").Code; got != 404 {
				t.Fatalf("first request: got %d want 404", got)
			}
			var n, l, w string
			var ok bool
			r.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
				n = c.Param("name")
				l = c.Params.ByName("last_name")
				w, ok = c.Params.Get("wild")
				c.String(http.StatusOK, "ok")
			})
			rec := do(r, http.MethodGet, "/test/john/smith/is/super/great")
			if rec.Code != 200 {
				t.Fatalf("second request: got %d want 200", rec.Code)
			}
			if n != "john" || l != "smith" || !ok || w != "/is/super/great" {
				t.Fatalf("params = %q,%q,%q,%v want john,smith,/is/super/great,true", n, l, w, ok)
			}
		})
	}
}

// maxParams grows repeatedly after requests have been served.
func TestLateRouteGrowingMaxParams(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	do(r, http.MethodGet, "/a/1")
	r.GET("/a/:x", func(c *gin.Context) { c.String(200, "x="+c.Param("x")) })
	if got := do(r, http.MethodGet, "/a/1").Body.String(); got != "x=1" {
		t.Fatalf("got %q want x=1", got)
	}
	do(r, http.MethodGet, "/b/1/2/3/4")
	r.GET("/b/:x/:y/:z/*rest", func(c *gin.Context) {
		c.String(200, "%s|%s|%s|%s", c.Param("x"), c.Param("y"), c.Param("z"), c.Param("rest"))
	})
	if got := do(r, http.MethodGet, "/b/1/2/3/4/5").Body.String(); got != "1|2|3|/4/5" {
		t.Fatalf("got %q want 1|2|3|/4/5", got)
	}
	// params must not leak between requests
	if got := do(r, http.MethodGet, "/a/9").Body.String(); got != "x=9" {
		t.Fatalf("got %q want x=9", got)
	}
	// 404 after late registration must not keep stale params
	rec := do(r, http.MethodGet, "/nope/1/2")
	if rec.Code != 404 {
		t.Fatalf("got %d want 404", rec.Code)
	}
}

// Late registration of a route with static + wildcard children (skippedNodes path).
func TestLateRouteSkippedNodesPath(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	do(r, http.MethodGet, "/user/new")
	r.GET("/user/new", func(c *gin.Context) { c.String(200, "static") })
	r.GET("/user/:id", func(c *gin.Context) { c.String(200, "id="+c.Param("id")) })
	if got := do(r, http.MethodGet, "/user/new").Body.String(); got != "static" {
		t.Fatalf("got %q want static", got)
	}
