func TestLateRouteHandleContext(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	do(r, http.MethodGet, "/hc/john/smith")
	r.GET("/hc/:name/:last_name", func(c *gin.Context) { c.String(200, c.Param("name")+"|"+c.Param("last_name")) })
