type myErr struct{ s string }

func (e *myErr) Error() string { return e.s }

func TestA_ErrorUnwrapValue(t *testing.T) {
	inner := &myErr{"inner"}
	err := gin.Error{Err: inner, Type: gin.ErrorTypeAny}
	wrapped := fmt.Errorf("wrapped: %w", err)

	if !errors.Is(wrapped, inner) {
		t.Errorf("errors.Is(wrapped, inner) = false, want true")
	}
	var target *myErr
	if !errors.As(wrapped, &target) {
		t.Errorf("errors.As(wrapped, &target) = false, want true")
	} else if target != inner {
		t.Errorf("errors.As target = %v, want %v", target, inner)
	}
	if errors.Unwrap(wrapped) != error(err) {
		t.Errorf("errors.Unwrap(wrapped) = %v, want %v", errors.Unwrap(wrapped), err)
	}
	t.Logf("value form OK: Is=%v As=%v target=%v", errors.Is(wrapped, inner), errors.As(wrapped, &target), target)
}

func TestA_ErrorUnwrapPointer(t *testing.T) {
	inner := &myErr{"inner"}
	perr := &gin.Error{Err: inner, Type: gin.ErrorTypeAny}
	wrapped := fmt.Errorf("wrapped: %w", perr)

	if !errors.Is(wrapped, inner) {
		t.Errorf("pointer form: errors.Is(wrapped, inner) = false, want true")
	}
	var target *myErr
	if !errors.As(wrapped, &target) {
		t.Errorf("pointer form: errors.As(wrapped, &target) = false, want true")
	} else if target != inner {
		t.Errorf("pointer form: errors.As target = %v, want %v", target, inner)
	}
