package verify

import (
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
)

// Router: several late registrations, growing maxParams/maxSections, pooled contexts.
func TestC_ExtraRouterLateRegistration(t *testing.T) {
	gin.SetMode(gin.TestMode)
	router := gin.New()
	// prime the pool with small slices
	for i := 0; i < 3; i++ {
		rec := httptest.NewRecorder()
		router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/nope", nil))
		if rec.Code != 404 {
			t.Fatalf("prime request %d code=%d want 404", i, rec.Code)
		}
	}
	router.GET("/test/:name/:last_name/*wild", func(c *gin.Context) {
		c.String(200, "%s|%s|%s", c.Param("name"), c.Param("last_name"), c.Param("wild"))
	})
	// a second, bigger route registered later too
	router.GET("/big/:a/:b/:c/:d/:e", func(c *gin.Context) {
		c.String(200, "%s%s%s%s%s", c.Param("a"), c.Param("b"), c.Param("c"), c.Param("d"), c.Param("e"))
	})
	for i := 0; i < 5; i++ {
		rec := httptest.NewRecorder()
		router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/test/john/smith/is/super/great", nil))
		if rec.Code != 200 || rec.Body.String() != "john|smith|/is/super/great" {
			t.Fatalf("iter %d: code=%d body=%q", i, rec.Code, rec.Body.String())
		}
		rec2 := httptest.NewRecorder()
		router.ServeHTTP(rec2, httptest.NewRequest(http.MethodGet, "/big/1/2/3/4/5", nil))
		if rec2.Code != 200 || rec2.Body.String() != "12345" {
			t.Fatalf("iter %d big: code=%d body=%q", i, rec2.Code, rec2.Body.String())
		}
	}
	t.Logf("late registration with pooled contexts OK")
}

// Response writer: WriteHeader after body written must not change status nor body.
func TestB_ExtraWriteHeaderAfterBody(t *testing.T) {
	gin.SetMode(gin.TestMode)
	router := gin.New()
	router.GET("/body", func(c *gin.Context) {
		c.Writer.WriteHeader(200)
		c.Writer.WriteString("hello")
		c.Writer.WriteHeader(401)
		if c.Writer.Status() != 200 {
			t.Errorf("in-handler Status()=%d want 200", c.Writer.Status())
		}
	})
	srv := httptest.NewServer(router)
	defer srv.Close()
	resp, err := http.Get(srv.URL + "/body")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	b, _ := ioutil.ReadAll(resp.Body)
	if resp.StatusCode != 200 || string(b) != "hello" {
		t.Errorf("status=%d body=%q want 200/hello", resp.StatusCode, b)
	}
	t.Logf("status=%d body=%q", resp.StatusCode, b)
}

// Response writer: WriteHeader(0) must be ignored; default 200 when nothing set.
func TestB_ExtraEdgeCases(t *testing.T) {
	gin.SetMode(gin.TestMode)
	c, _ := gin.CreateTestContext(httptest.NewRecorder())
	if c.Writer.Status() != 200 {
		t.Errorf("default Status()=%d want 200", c.Writer.Status())
	}
	c.Writer.WriteHeader(0)
	if c.Writer.Status() != 200 {
		t.Errorf("after WriteHeader(0) Status()=%d want 200", c.Writer.Status())
	}
	c.Writer.WriteHeader(404)
	c.Writer.WriteHeader(500)
	if c.Writer.Status() != 404 {
		t.Errorf("Status()=%d want 404 (last-wins before write)", c.Writer.Status())
	}
	t.Logf("edge cases OK, final Status()=%d", c.Writer.Status())
}
EOF
