package verify

import (
	"errors"
	"fmt"
	"testing"

	"github.com/gin-gonic/gin"
)

func TestA_SentinelAndUnwrapChain(t *testing.T) {
	sentinel := errors.New("sentinel")
	gerr := gin.Error{Err: sentinel, Type: gin.ErrorTypeAny}
	wrapped := fmt.Errorf("wrapped: %w", gerr)
	if !errors.Is(wrapped, sentinel) {
		t.Error("errors.Is(wrapped, sentinel) = false")
	}
	// Unwrap chain: wrapped -> gin.Error -> sentinel
	if got := errors.Unwrap(errors.Unwrap(wrapped)); got != sentinel {
		t.Errorf("deep unwrap = %v, want sentinel", got)
	}
	// value gin.Error itself still usable as error
	var e error = gerr
	if e.Error() != "sentinel" {
		t.Errorf("Error() = %q", e.Error())
	}
	// pointer form with As to *gin.Error
	perr := &gin.Error{Err: sentinel, Type: gin.ErrorTypeAny}
	pwrapped := fmt.Errorf("w: %w", perr)
	var target *gin.Error
	if !errors.As(pwrapped, &target) || target != perr {
		t.Errorf("errors.As pointer form failed: %v", target)
	}
	// gin's own errorMsgs still work
	c := &gin.Context{Errors: gin.ErrorMsgs{}}
	_ = c
	t.Log("sentinel/chain/pointer checks OK")
}
EOF
