package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func scratchCtx(accept string) *Context {
	c, _ := CreateTestContext(httptest.NewRecorder())
	c.Request, _ = http.NewRequest("POST", "/", nil)
	if accept != "" {
		c.Request.Header.Set("Accept", accept)
	}
	return c
}

func TestScratchNegotiateFormatPrefix(t *testing.T) {
	cases := []struct {
		accept  string
		offers  []string
		want    string
	}{
		{"image/tiff-fx", []string{"image/tiff"}, ""},                    // reported panic
		{"image/tiff", []string{"image/tiff-fx"}, ""},                    // reverse prefix
		{"image/tiff-fx", []string{"image/tiff", "image/png"}, ""},       // no match among several
		{"image/tiff-fx", []string{"image/tiff-fx"}, "image/tiff-fx"},    // exact still matches
		{"image/tiff", []string{"image/tiff-fx", "image/tiff"}, "image/tiff"},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEJSON, MIMEXML}, MIMEXML},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEJSON}, ""},
		{"*/*", []string{MIMEJSON}, MIMEJSON},
		{"text/*", []string{"text/html"}, "text/html"},
		{"text/html", []string{"text/*"}, "text/*"},
		{"text/*", []string{MIMEJSON}, ""},
		{"application/json", []string{"application/json; charset=utf-8"}, ""}, // prefix, not equal
		{"", []string{MIMEJSON, MIMEXML}, MIMEJSON},                           // no Accept header
	}
	for _, tc := range cases {
		got := scratchCtx(tc.accept).NegotiateFormat(tc.offers...)
		if got != tc.want {
			t.Errorf("Accept=%q offers=%v: got %q want %q", tc.accept, tc.offers, got, tc.want)
		} else {
			t.Logf("ok Accept=%-55q offers=%-30v -> %q", tc.accept, tc.offers, got)
		}
	}
}

func TestScratchNegotiatePrefixNoPanic(t *testing.T) {
	w := httptest.NewRecorder()
	c, _ := CreateTestContext(w)
	c.Request, _ = http.NewRequest("POST", "/", nil)
	c.Request.Header.Set("Accept", "image/tiff-fx")
	c.Negotiate(http.StatusOK, Negotiate{Offered: []string{"image/tiff"}})
	if w.Code != http.StatusNotAcceptable {
		t.Fatalf("expected 406, got %d", w.Code)
	}
	t.Logf("Negotiate with prefix Accept -> status %d (no panic)", w.Code)
}
EOF
