func TestZZReproRedirectFixedPathWildcard(t *testing.T) {
	SetMode(TestMode)
	r := New()
	r.RedirectFixedPath = true
	h := func(c *Context) { c.String(http.StatusOK, "ok") }
	r.GET("/prefix/:id", h)
	r.GET("/prefix/xxx", h)

	// /PREFIX/XXX should redirect to /prefix/xxx
	w := httptest.NewRecorder()
	req, _ := http.NewRequest(http.MethodGet, "/PREFIX/XXX", nil)
	r.ServeHTTP(w, req)
	t.Logf("/PREFIX/XXX -> code=%d location=%q", w.Code, w.Header().Get("Location"))
	if w.Code != http.StatusMovedPermanently {
		t.Errorf("/PREFIX/XXX: got code %d, want 301", w.Code)
	}
	if loc := w.Header().Get("Location"); loc != "/prefix/xxx" {
		t.Errorf("/PREFIX/XXX: got location %q, want /prefix/xxx", loc)
	}

	// /prefix/a/b/c should 404, no panic
	w2 := httptest.NewRecorder()
	req2, _ := http.NewRequest(http.MethodGet, "/prefix/a/b/c", nil)
	r.ServeHTTP(w2, req2)
	t.Logf("/prefix/a/b/c -> code=%d location=%q", w2.Code, w2.Header().Get("Location"))
	if w2.Code != http.StatusNotFound {
		t.Errorf("/prefix/a/b/c: got code %d, want 404", w2.Code)
	}
}
