		{"image/tiff", []string{"image/tiff-fx"}, "image/tiff-fx"},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{gin.MIMEJSON, gin.MIMEXML}, gin.MIMEXML},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{gin.MIMEXML, gin.MIMEHTML}, gin.MIMEHTML},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{gin.MIMEJSON}, ""},
		{"*/*", []string{"text/*"}, "text/*"},
		{"text/*", []string{gin.MIMEHTML}, gin.MIMEHTML},
		{"text/*", []string{gin.MIMEJSON}, ""},
	}
	for _, tc := range cases {
		c := newCtx(tc.accept)
		got := c.NegotiateFormat(tc.offered...)
		t.Logf("Accept=%q offered=%v -> %q (want %q)", tc.accept, tc.offered, got, tc.want)
		if got != tc.want {
			t.Errorf("Accept=%q offered=%v: got %q, want %q", tc.accept, tc.offered, got, tc.want)
